<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\{Brand,User}; use App\Services\AuditService; use Illuminate\Http\Request; use Illuminate\Support\Facades\Hash; use Illuminate\Validation\Rule;
class UserController extends Controller { public function index(){ $this->authorize('manage',User::class);return view('admin.users.index',['users'=>User::with('brands')->orderBy('name')->get()]);} public function create(){ $this->authorize('manage',User::class);return view('admin.users.form',['item'=>new User,'brands'=>Brand::orderBy('name')->get()]);} public function store(Request $r,AuditService $audit){$this->authorize('manage',User::class);$data=$this->valid($r);$brandIds=$data['brand_ids']??[];unset($data['brand_ids']);$data['password']=Hash::make($data['password']);$u=User::create($data);$u->brands()->sync($u->role==='brand_admin'?$brandIds:[]);$audit->record('users.created',$u,[],$u->only('name','email','role','status'));return redirect()->route('admin.users.edit',$u)->with('status','使用者已建立。');} public function edit(User $user){$this->authorize('manage',User::class);return view('admin.users.form',['item'=>$user,'brands'=>Brand::orderBy('name')->get()]);} public function update(Request $r,User $user,AuditService $audit){$this->authorize('manage',User::class);$data=$this->valid($r,$user);$brandIds=$data['brand_ids']??[];unset($data['brand_ids']);if(empty($data['password']))unset($data['password']);else $data['password']=Hash::make($data['password']);if($user->role==='super_admin'&&($data['role']!=='super_admin'||$data['status']!=='active'))abort_if(User::where('role','super_admin')->where('status','active')->whereKeyNot($user->id)->doesntExist(),422,'不可停用或移除最後一名總管理者。');$before=$user->load('brands')->toArray();$user->update($data);$user->brands()->sync($user->role==='brand_admin'?$brandIds:[]);$audit->record('users.updated',$user,$before,$user->fresh('brands')->toArray());return back()->with('status','使用者已更新。');} private function valid(Request $r,?User $u=null):array{return $r->validate(['name'=>'required|string|max:100','email'=>['required','email','max:255',Rule::unique('users')->ignore($u?->id)],'password'=>[$u?'nullable':'required','confirmed','min:10'],'role'=>['required',Rule::in(User::ROLES)],'status'=>'required|in:active,disabled','brand_ids'=>'nullable|array','brand_ids.*'=>'integer|exists:brands,id']);}}
